INSERT INTO monster VALUES (579,'Swarm','Spider Swarm',NULL,'Diminutive','Vermin','Swarm','2d8 (9 hp)','+3','20 ft. (4 squares), climb 20 ft.','17 (+4 size, +3 Dex), touch 17, flat-footed 14','+1','-','Swarm (1d6 plus poison)','Swarm (1d6 plus poison)','10 ft.','0 ft.','Distraction, poison','Darkvision 60 ft., swarm traits, tremorsense 30 ft., vermin traits','Fort +3, Ref +3, Will +0','Str 1, Dex 17, Con 10, Int -, Wis 10, Cha 2','Climb +11, Listen +4, Spot +4',NULL,NULL,NULL,'Warm forests','Solitary, tangle (2-4 swarms), or colony (7-12 swarms)','1','None','Always neutral','None','-','Distraction (Ex), Poison (Ex)','Spider swarm; CR 1; Diminutive vermin (swarm); HD 2d8; hp 9; Init +3; Spd 20 ft. (4 squares), climb 20 ft.; AC 17 (+4 size, +3 dex), touch 17, flat-footed 14; Base Atk +1; Grp -; Atk Swarm (1d6 plus poison); Full Atk Swarm (1d6 plus poison); Space/Reach 10 ft./0 ft.; SA Distraction, poison; SQ Darkvision 60 ft., swarm traits, tremorsense 30 ft., vermin traits; AL N; SV Fort +3, Ref +3, Will +0; Str 1, Dex 17, Con 10, Int -, Wis 10, Cha 2\n\nSkills and Feats: Climb +11, Listen +4, Spot +4; ','\n      <div topic=\"Spider Swarm\" level=\"3\"><p><h3>Spider Swarm</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Spider Swarm</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Diminutive Vermin (Swarm)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>2d8 (9 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), climb 20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>17 (+4 size, +3 Dex), touch 17, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Swarm (1d6 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Swarm (1d6 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./0 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Distraction, poison<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., swarm traits, tremorsense 30 ft., vermin traits<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +3, Will +0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 1, Dex 17, Con 10, Int -, Wis 10, Cha 2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +11, Listen +4, Spot +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm forests<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, tangle (2-4 swarms), or colony (7-12 swarms)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A spider swarm seeks to surround and attack any living prey it encounters. A swarm deals 1d6 points of damage to any creature whose space it occupies at the end of its move.</p><div topic=\"Distraction\" level=\"8\"><p><b>Distraction (Ex):</b> Any living creature that begins its turn with a spider swarm in its space must succeed on a DC 11 Fortitude save or be nauseated for 1 round. The save DC is Constitution-based.</p>\n</div><div topic=\"Poison\" level=\"8\"><p><b>Poison (Ex):</b> Injury, Fortitude DC 11, initial and secondary damage 1d3 Str. The save DC is Constitution-based.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A spider swarm has a +4 racial bonus on Hide and Spot checks and a +8 racial bonus on Climb checks. It uses its Dexterity modifier instead of its Strength modifier for Climb checks. It can always choose to take 10 on a Climb check, even if rushed or threatened.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersS');
INSERT INTO monster VALUES (580,'Tarrasque','Tarrasque',NULL,'Colossal','Magical Beast',NULL,'48d10+594 (858 hp)','+7','20 ft. (4 squares)','35 (-8 size, +3 Dex, +30 natural), touch 5, flat-footed 32','+48','+81','Bite +57 melee (4d8+17/18-20/x3)','Bite +57 melee (4d8+17/18-20/x3) and 2 horns +52 melee (1d10+8) and 2 claws +52 melee (1d12+8) and tail slap +52 melee (3d8+8)','30 ft.','20 ft.','Augmented critical, frightful presence, improved grab, rush, swallow whole','Carapace, damage reduction 15/epic, immunity to fire, poison, disease, energy drain, and ability damage, regeneration 40, scent, spell resistance 32','Fort +38, Ref +29, Will +20','Str 45, Dex 16, Con 35, Int 3, Wis 14, Cha 14','Listen +17, Search +9, Spot +17, Survival +14 (+16 following tracks)',NULL,'Alertness, Awesome Blow, Blind-Fight, Cleave, Combat Reflexes, Dodge, Great Cleave, Improved Bull Rush, Improved Initiative, Iron Will, Power Attack, Toughness (6)',NULL,'Any','Solitary','20','None','Always neutral','49+ HD (Colossal)','-','Augmented Critical (Ex), Carapace (Ex), Frightful Presence (Su), Improved Grab (Ex), Regeneration (Ex), Rush (Ex), Swallow Whole (Ex)','Tarrasque; CR 20; Colossal magical beast; HD 48d10+594; hp 858; Init +7; Spd 20 ft. (4 squares); AC 35 (-8 size, +3 dex, +30 natural), touch 5, flat-footed 32; Base Atk +48; Grp +81; Atk +57 melee (4d8+17/18-20/x3, bite); Full Atk +57 melee (4d8+17/18-20/x3, bite) and +52 melee (1d10+8, 2 horns) and +52 melee (1d12+8, 2 claws) and +52 melee (3d8+8, tail slap); Space/Reach 30 ft./20 ft.; SA Augmented critical, frightful presence, improved grab, rush, swallow whole; SQ Carapace, damage reduction 15/epic, immunity to fire, poison, disease, energy drain, and ability damage, regeneration 40, scent, spell resistance 32; AL N; SV Fort +38, Ref +29, Will +20; Str 45, Dex 16, Con 35, Int 3, Wis 14, Cha 14\n\nSkills and Feats: Listen +17, Search +9, Spot +17, Survival +14 (+16 following tracks); Alertness, Awesome Blow, Blind-Fight, Cleave, Combat Reflexes, Dodge, Great Cleave, Improved Bull Rush, Improved Initiative, Iron Will, Power Attack, Toughness (6)','\n      <div topic=\"Tarrasque\" level=\"2\"><p><h2>Tarrasque</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Tarrasque</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Colossal Magical Beast<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>48d10+594 (858 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>35 (-8 size, +3 Dex, +30 natural), touch 5, flat-footed 32<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+48/+81<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +57 melee (4d8+17/18-20/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +57 melee (4d8+17/18-20/x3) and 2 horns +52 melee (1d10+8) and 2 claws +52 melee (1d12+8) and tail slap +52 melee (3d8+8)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>30 ft./20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Augmented critical, frightful presence, improved grab, rush, swallow whole<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Carapace, damage reduction 15/epic, immunity to fire, poison, disease, energy drain, and ability damage, regeneration 40, scent, spell resistance 32<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +38, Ref +29, Will +20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 45, Dex 16, Con 35, Int 3, Wis 14, Cha 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +17, Search +9, Spot +17, Survival +14 (+16 following tracks)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Awesome Blow, Blind-Fight, Cleave, Combat Reflexes, Dodge, Great Cleave, Improved Bull Rush, Improved Initiative, Iron Will, Power Attack, Toughness (6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>49+ HD (Colossal)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>The tarrasque is 70 feet long and 50 feet tall, and it weighs about 130 tons.</p><p>The tarrasque cannot speak.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>The tarrasque attacks with its claws, teeth, horns, and tail.</p><p>The tarrasque\'s natural weapons are treated as epic weapons for the purpose of overcoming damage reduction.</p><div topic=\"Augmented Critical\" level=\"8\"><p><b>Augmented Critical (Ex):</b> The tarrasque\'s bite threatens a critical hit on a natural attack roll of 18-20, dealing triple damage on a successful critical hit.</p>\n</div><div topic=\"Frightful Presence\" level=\"8\"><p><b>Frightful Presence (Su):</b> The tarrasque can inspire terror by charging or attacking. Affected creatures must succeed on a DC 36 Will save or become shaken, remaining in that condition as long as they remain with 60 feet of the tarrasque. The save DC is Charisma-based.</p>\n</div><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, the tarrasque must hit a Huge or smaller opponent with its bite attack. It can then attempt to start a grapple as a free action without provoking an attack of opportunity. If it wins the grapple check, it establishes a hold and can try to swallow the foe the following round.</p>\n</div><div topic=\"Rush\" level=\"8\"><p><b>Rush (Ex):</b> Once per minute, the normally slow-moving tarrasque can move at a speed of 150 feet.</p>\n</div><div topic=\"Swallow Whole\" level=\"8\"><p><b>Swallow Whole (Ex):</b> The tarrasque can try to swallow a grabbed opponent of Huge or smaller size by making a successful grapple check. Once inside, the opponent takes 2d8+8 points of crushing damage plus 2d8+6 points of acid damage per round from the tarrasque\'s digestive juices. A swallowed creature can cut its way out by dealing 50 points of damage to the tarrasque\'s digestive tract (AC 25). Once the creature exits, muscular action closes the hole; another swallowed opponent must cut its own way out. The tarrasque\'s gullet can hold 2 Huge, 8 Large, 32 Medium, 128 Small, or 512 Tiny or smaller creatures.</p>\n</div><div topic=\"Carapace\" level=\"8\"><p><b>Carapace (Ex):</b> The tarrasque\'s armorlike carapace is exceptionally tough and highly reflective, deflecting all rays, lines, cones, and even <i>magic missile</i> spells. There is a 30% chance of reflecting any such effect back at the caster; otherwise, it is merely negated. Check for reflection before rolling to overcome the creature\'s spell resistance.</p>\n</div><div topic=\"Regeneration\" level=\"8\"><p><b>Regeneration (Ex):</b> No form of attack deals lethal damage to the tarrasque. The tarrasque regenerates even if it fails a saving throw against a <i>disintegrate</i> spell or a death effect. If the tarrasque fails its save against a spell or effect that would kill it instantly (such as those mentioned above), the spell or effect instead deals nonlethal damage equal to the creature\'s full normal hit points +10 (or 868 hp). The tarrasque is immune to effects that produce incurable or bleeding wounds, such as mummy rot, a sword with the wounding special ability, or a clay golem\'s cursed wound ability.</p><p>The tarrasque can be slain only by raising its nonlethal damage total to its full normal hit points +10 (or 868 hit points) and using a <i>wish</i> or <i>miracle</i> spell to keep it dead.</p><p>If the tarrasque loses a limb or body part, the lost portion regrows in 1d6 minutes (the detached piece dies and decays normally). The creature can reattach the severed member instantly by holding it to the stump.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> The tarrasque has a +8 racial bonus on Listen and Spot checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (581,'Tendriculos','Tendriculos',NULL,'Huge','Plant',NULL,'9d8+54 (94 hp)','-1','20 ft. (4 squares)','16 (-2 size, -1 Dex, +9 natural), touch 7, flat-footed 16','+6','+23','Bite +13 melee (2d8+9) and 2 tendrils +8 melee (1d6+4)','Bite +13 melee (2d8+9) and 2 tendrils +8 melee (1d6+4)','15 ft.','15 ft.','Improved grab, paralysis, swallow whole','Low-light vision, plant traits, regeneration 10','Fort +12, Ref +2, Will +4','Str 28, Dex 9, Con 22, Int 3, Wis 8, Cha 3','Hide +9, Listen +1, Move Silently +1, Spot +1',NULL,'Alertness, Iron Will, Power Attack, Stealthy',NULL,'Temperate forests','Solitary','6','1/10th coins; 50% goods; 50% items','Always neutral','10-16 HD (Huge); 17-27 HD (Gargantuan)','-','Improved Grab (Ex), Regeneration (Ex), Swallow Whole/Paralysis (Ex)','Tendriculos; CR 6; Huge plant; HD 9d8+54; hp 94; Init -1; Spd 20 ft. (4 squares); AC 16 (-2 size, -1 dex, +9 natural), touch 7, flat-footed 16; Base Atk +6; Grp +23; Atk +13 melee (2d8+9, bite) or +8 melee (1d6+4, 2 tendrils); Full Atk +13 melee (2d8+9, bite) and +8 melee (1d6+4, 2 tendrils); Space/Reach 15 ft./15 ft.; SA Improved grab, paralysis, swallow whole; SQ Low-light vision, plant traits, regeneration 10; AL N; SV Fort +12, Ref +2, Will +4; Str 28, Dex 9, Con 22, Int 3, Wis 8, Cha 3\n\nSkills and Feats: Hide +9, Listen +1, Move Silently +1, Spot +1; Alertness, Iron Will, Power Attack, Stealthy','\n      <div topic=\"Tendriculos\" level=\"2\"><p><h2>Tendriculos</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Tendriculos</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Huge Plant<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>9d8+54 (94 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>-1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (-2 size, -1 Dex, +9 natural), touch 7, flat-footed 16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+6/+23<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +13 melee (2d8+9) and 2 tendrils +8 melee (1d6+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +13 melee (2d8+9) and 2 tendrils +8 melee (1d6+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./15 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Improved grab, paralysis, swallow whole<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision, plant traits, regeneration 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +12, Ref +2, Will +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 28, Dex 9, Con 22, Int 3, Wis 8, Cha 3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +9, Listen +1, Move Silently +1, Spot +1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Iron Will, Power Attack, Stealthy<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate forests<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>1/10th coins; 50% goods; 50% items<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>10-16 HD (Huge); 17-27 HD (Gargantuan)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A tendriculos can rear up to a height of 15 feet. It weighs about 3,500 pounds.</p><p>Animals and other plant creatures are unnerved by the presence of a tendriculos; they avoid it and any place it has been within the last 24 hours.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Prowling deep forests or waiting in vegetated areas (looking like nothing more than a small hillock), a tendriculos attacks savagely, showing no fear. It attempts to swallow as much flesh as it can, as quickly as it can.</p><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a tendriculos must hit a creature at least one size smaller than itself with its bite attack. It can then attempt to start a grapple as a free action without provoking an attack of opportunity. If it wins the grapple check, it establishes a hold and can try to swallow the opponent in the following round. A tendriculos can also use its improved grab ability on a tendril attack. If it wins the grapple check, it establishes a hold, picks up the opponent, and transfers it to the mouth as a free action, automatically dealing bite damage.</p>\n</div><div topic=\"Swallow Whole/Paralysis\" level=\"8\"><p><b>Swallow Whole/Paralysis (Ex):</b> A tendriculos can try to swallow a grabbed opponent by making a successful grapple check. Once inside the plant\'s mass, the opponent must succeed on a DC 20 Fortitude save or be paralyzed for 3d6 rounds by the tendriculos\'s digestive juices, taking 2d6 points of acid damage per round. A new save is required each round inside the plant. The save DC is Constitution-based. A swallowed creature that avoids paralysis can climb out of the mass with a successful grapple check. This returns it to the plant\'s maw, where another successful grapple check is needed to get free. A swallowed creature can also cut its way out by using a light slashing or piercing weapon to deal 25 points of damage to the tendriculos\'s interior (AC 14). Once the creature exits, the plant\'s regenerative capacity closes the hole; another swallowed opponent must cut its own way out. A Huge tendriculos\'s interior can hold 2 Large, 8 Medium, 32 Small, 128 Tiny, or 512 Diminutive or smaller opponents.</p>\n</div><div topic=\"Regeneration\" level=\"8\"><p><b>Regeneration (Ex):</b> Bludgeoning weapons and acid deal normal damage to a tendriculos. A tendriculos that loses part of its body mass can regrow it in 1d6 minutes. Holding the severed portion against the mass enables it to reattach instantly.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (582,'Thoqqua','Thoqqua',NULL,'Medium','Elemental','Earth, Extraplanar, Fire','3d8+3 (16 hp)','+1','30 ft. (6 squares), burrow 20 ft.','18 (+1 Dex, +7 natural), touch 11, flat-footed 17','+2','+4','Slam +4 melee (1d6+3 plus 2d6 fire)','Slam +4 melee (1d6+3 plus 2d6 fire)','5 ft.','5 ft.','Heat, burn','Darkvision 60 ft., elemental traits, immunity to fire, tremorsense 60 ft., vulnerability to cold','Fort +4, Ref +2, Will +2','Str 15, Dex 13, Con 13, Int 6, Wis 12, Cha 10','Listen +5, Move Silently +3, Survival +3',NULL,'Alertness, Track',NULL,'Elemental Plane of Fire','Solitary or pair','2','None','Usually neutral','4-9 HD (Large)','-','Burn (Ex), Heat (Ex)','Thoqqua; CR 2; Medium elemental (earth, extraplanar, fire); HD 3d8+3; hp 16; Init +1; Spd 30 ft. (6 squares), burrow 20 ft.; AC 18 (+1 dex, +7 natural), touch 11, flat-footed 17; Base Atk +2; Grp +4; Atk +4 melee (1d6+3 plus 2d6 fire, slam); Full Atk +4 melee (1d6+3 plus 2d6 fire, slam); Space/Reach 5 ft./5 ft.; SA Heat, burn; SQ Darkvision 60 ft., elemental traits, immunity to fire, tremorsense 60 ft., vulnerability to cold; AL N; SV Fort +4, Ref +2, Will +2; Str 15, Dex 13, Con 13, Int 6, Wis 12, Cha 10\n\nSkills and Feats: Listen +5, Move Silently +3, Survival +3; Alertness, Track','\n      <div topic=\"Thoqqua\" level=\"2\"><p><h2>Thoqqua</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Thoqqua</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Elemental (Earth, Extraplanar, Fire)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>3d8+3 (16 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares), burrow 20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>18 (+1 Dex, +7 natural), touch 11, flat-footed 17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+2/+4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Slam +4 melee (1d6+3 plus 2d6 fire)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Slam +4 melee (1d6+3 plus 2d6 fire)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Heat, burn<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., elemental traits, immunity to fire, tremorsense 60 ft., vulnerability to cold<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +4, Ref +2, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 15, Dex 13, Con 13, Int 6, Wis 12, Cha 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +5, Move Silently +3, Survival +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Track<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Elemental Plane of Fire<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or pair<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>4-9 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A thoqqua is about 1 foot in diameter and 4 to 5 feet long. It weighs about 200 pounds.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>When a thoqqua is disturbed, its first instinct is to attack. Its favored tactic is to spring directly at a foe, either by bursting out of the rock or by coiling up its body and launching itself like a spring. (Treat this as a charge, even though the thoqqua does not need to move 10 feet before attacking.)</p><div topic=\"Heat\" level=\"8\"><p><b>Heat (Ex):</b> Merely touching or being touched by a thoqqua automatically deals 2d6 fire damage.</p>\n</div><div topic=\"Burn\" level=\"8\"><p><b>Burn (Ex):</b> When a thoqqua hits with its slam attack, the opponent must succeed on a DC 12 Reflex save or catch fire. The save DC is Constitution-based. The flame burns for 1d4 rounds if not extinguished sooner. A burning creature can use a full-round action to put out the flame.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (583,'Titan','Titan',NULL,'Huge','Outsider','Chaotic, Extraplanar','20d8+280 (370 hp)','+1','40 ft. in half-plate armor (8 squares); base speed 60 ft.','38 (-2 size, +19 natural, +11 +4 half-plate armor), touch 8, flat-footed 38','+20','+44','Gargantuan +3 adamantine warhammer +37 melee (4d6+27/x3) or +3 javelin +22 ranged (2d6+19) or slam +34 (1d8+16)','Gargantuan +3 adamantine warhammer +37/+32/+27/+22 melee (4d6+27/3) or +3 javelin +22 ranged (2d6+19) or 2 slams +34 (1d8+16)','15 ft.','15 ft.','Oversized weapon, spell-like abilities','Damage reduction 15/lawful, darkvision 60 ft., spell resistance 32','Fort +26, Ref +13, Will +21','Str 43, Dex 12, Con 39, Int 21, Wis 28, Cha 24','Balance +7, Bluff +19, Climb +22, Concentration +37, Craft (any one) +28, Diplomacy +11, Disguise +7 (+9 acting), Heal +20, Intimidate +32, Jump +38, Knowledge (any one) +28, Listen +32, Perform (oratory) +30, Sense Motive +32, Search +28, Spellcraft +17, Spot +32, Survival +9 (+11 following tracks), Swim +16',NULL,'Awesome Blow, Blind-Fight, Cleave, Improved Bull Rush, Improved Sunder, Power Attack, Quicken Spell-Like Ability (chain lightning)',NULL,'A chaotic good-aligned plane','Solitary or pair','21','Double standard plus +4 half-plate armor and Gargantuan +3 adamantine warhammer','Always chaotic (any)','21-30 HD (Huge); 31-60 HD (Gargantuan)','-','Oversized Weapon (Ex)','Titan; CR 21; Huge outsider (chaotic, extraplanar); HD 20d8+280; hp 370; Init +1; Spd 40 ft. in half-plate armor (8 squares); base speed 60 ft.; AC 38 (-2 size, +19 natural, +11 +4 half-plate armor), touch 8, flat-footed 38; Base Atk +20; Grp +44; Atk +3 adamantine warhammer +37 melee (4d6+27/x3, gargantuan) or +3 javelin +22 ranged (2d6+19,) or +34 (1d8+16, slam); Full Atk +3 adamantine warhammer +37/+32/+27/+22 melee (4d6+27/3, gargantuan) or +3 javelin +22 ranged (2d6+19,) or +34 (1d8+16, 2 slams); Space/Reach 15 ft./15 ft.; SA Oversized weapon, spell-like abilities; SQ Damage reduction 15/lawful, darkvision 60 ft., spell resistance 32; AL CN; SV Fort +26, Ref +13, Will +21; Str 43, Dex 12, Con 39, Int 21, Wis 28, Cha 24\n\nSkills and Feats: Balance +7, Bluff +19, Climb +22, Concentration +37, Craft (any one) +28, Diplomacy +11, Disguise +7 (+9 acting), Heal +20, Intimidate +32, Jump +38, Knowledge (any one) +28, Listen +32, Perform (oratory) +30, Sense Motive +32, Search +28, Spellcraft +17, Spot +32, Survival +9 (+11 following tracks), Swim +16; Awesome Blow, Blind-Fight, Cleave, Improved Bull Rush, Improved Sunder, Power Attack, Quicken Spell-Like Ability (chain lightning)','\n      <div topic=\"Titan\" level=\"2\"><p><h2>Titan</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Titan</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Huge Outsider (Chaotic, Extraplanar)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>20d8+280 (370 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. in half-plate armor (8 squares); base speed 60 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>38 (-2 size, +19 natural, +11 <i>+4 half-plate armor</i>), touch 8, flat-footed 38<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+20/+44<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Gargantuan <i>+3 adamantine warhammer</i> +37 melee (4d6+27/x3) or <i>+3 javelin</i> +22 ranged (2d6+19) or slam +34 (1d8+16)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Gargantuan <i>+3 adamantine warhammer</i> +37/+32/+27/+22 melee (4d6+27/3) or <i>+3 javelin</i> +22 ranged (2d6+19) or 2 slams +34 (1d8+16)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./15 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Oversized weapon, spell-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Damage reduction 15/lawful, darkvision 60 ft., spell resistance 32<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +26, Ref +13, Will +21<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 43, Dex 12, Con 39, Int 21, Wis 28, Cha 24<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Balance +7, Bluff +19, Climb +22, Concentration +37, Craft (any one) +28, Diplomacy +11, Disguise +7 (+9 acting), Heal +20, Intimidate +32, Jump +38, Knowledge (any one) +28, Listen +32, Perform (oratory) +30, Sense Motive +32, Search +28, Spellcraft +17, Spot +32, Survival +9 (+11 following tracks), Swim +16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Awesome Blow, Blind-Fight, Cleave, Improved Bull Rush, Improved Sunder, Power Attack, Quicken Spell-Like Ability (<i>chain lightning</i>)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>A chaotic good-aligned plane<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or pair<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>21<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Double standard plus <i>+4 half-plate armor</i> and Gargantuan <i>+3 adamantine warhammer</i><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always chaotic (any)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>21-30 HD (Huge); 31-60 HD (Gargantuan)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A titan is about 25 feet tall and weighs about 14,000 pounds.</p><p>Titans speak Abyssal, Common, Celestial, Draconic, and Giant.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A titan\'s natural weapons, as well as any weapons it wields, are treated as chaotic-aligned for the purpose of overcoming damage reduction.</p><div topic=\"Oversized Weapon\" level=\"8\"><p><b>Oversized Weapon (Ex):</b> A titan wields a great, two-handed warhammer (big enough for Gargantuan creatures) without penalty.</p>\n</div><div topic=\"Spell-Like Abilities\" level=\"8\"><p><b>Spell-Like Abilities:</b> At will-<i>chain lightning</i> (DC 23), <i>charm monster</i> (DC 21), <i>cure critical wounds</i> (DC 21), <i>fire storm</i> (DC 24), <i>greater dispel magic</i>,  <i>hold monster</i> (DC 22), <i>invisibility</i>,  <i>invisibility purge</i>,  <i>levitate</i>,  <i>persistent image</i> (DC 22), <i>polymorph</i> (humanoid forms only, duration 1 hour); 3/day-<i>etherealness</i>,  <i>word of chaos</i> (DC 22), <i>summon nature\'s ally IX</i>; 1/day-<i>gate</i>,  <i>maze</i>,  <i>meteor swarm</i> (DC 26). Caster level 20th. The save DCs are Charisma-based.</p><p>In addition, titans of good or neutral alignment can use the following additional spell-like abilities: At will-<i>daylight</i>,  <i>holy smite</i> (DC 21), <i>remove curse</i> (DC 21); 1/day-<i>greater restoration</i>. Caster level 20th. The save DCs are Charisma-based.</p><p>Titans of evil alignment can use the following additional spell-like abilities: At will-<i>bestow curse</i> (DC 21), <i>deeper darkness</i>,  <i>unholy blight</i> (DC 21); 1/day-<i>crushing hand</i> (DC 26). Caster level 20th. The save DCs are Charisma-based.</p>\n</div>\n</div><div topic=\"Tactics Round-by-Round\" level=\"3\"><p><h3>Tactics Round-by-Round</h3></p><p>Titans enjoy combat and usually close with their foes. If that proves ineffective, they swiftly back off and pelt the foe with spell-like abilities and magical effects. Because of a titan\'s Quicken Spell-Like Ability feat, it can use <i>chain lightning</i> as a free action, and frequently attacks in melee while lashing out with this ability at the same time.</p><p><i>Prior to combat: Invisibility purge</i> or <i>invisibility</i>.</p><p><i>Round 1:</i> Charge and attempt to sunder the weapon of the most dangerous foe. Hurl <i>chain lightning</i> at opponents standing away from the fight.</p><p><i>Round 2:</i> Full attack against the disarmed opponent, and hurl <i>chain lightning</i> at other opponents.</p><p><i>Round 3:</i> Back away from first opponent and use <i>maze</i> or <i>meteor swarm</i> on any spellcaster causing trouble.</p><p><i>Round 4:</i> Sunder the weapon of the next most effective combatant, or use <i>greater dispel magic</i> on all nearby opponents.</p><p><i>Round 5:</i> Full attack against any nearby opponent, or use <i>fire storm</i>.</p><p>Use another quickened <i>chain lightning</i> if foes seem really dangerous.</p><p>A titan usually reserves its <i>gate</i> and <i>etherealness</i> abilities to escape a fight that is not going well.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (584,'Tojanida','Juvenile Tojanida',NULL,'Small','Outsider','Extraplanar, Water','3d8+6 (19 hp)','+1','10 ft. (2 squares), swim 90 ft.','22 (+1 size, +1 Dex, +10 natural), touch 12, flat-footed 21','+3','+1','Bite +6 melee (2d6+2)','Bite +6 melee (2d6+2) and 2 claws +1 melee (1d4+1)','5 ft.','5 ft.','Improved grab, ink cloud','All-around vision, darkvision 60 ft., immunity to acid and cold, resistance to','Fort +5, Ref +4, Will +4','Str 14, Dex 13, Con 15, Int 10, Wis 12, Cha 9','Diplomacy +1, Escape Artist +7, Hide +11, Knowledge (the planes) +6, Listen +7, Search +6, Spot +9, Sense Motive +7, Survival +1 (+3 other planes and following tracks), Swim +10, Use Rope +1 (+3 with bindings)',NULL,'Blind-Fight, Dodge',NULL,'Elemental Plane of Water','Solitary or clutch (2-4)','3','Standard','Always neutral','4-6 HD (Small)','-','All-Around Vision (Ex), Improved Grab (Ex), Ink Cloud (Ex)','Juvenile tojanida; CR 3; Small outsider (extraplanar, water); HD 3d8+6; hp 19; Init +1; Spd 10 ft. (2 squares), swim 90 ft.; AC 22 (+1 size, +1 dex, +10 natural), touch 12, flat-footed 21; Base Atk +3; Grp +1; Atk +6 melee (2d6+2, bite); Full Atk +6 melee (2d6+2, bite) and +1 melee (1d4+1, 2 claws); Space/Reach 5 ft./5 ft.; SA Improved grab, ink cloud; SQ All-around vision, darkvision 60 ft., immunity to acid and cold, resistance to; AL N; SV Fort +5, Ref +4, Will +4; Str 14, Dex 13, Con 15, Int 10, Wis 12, Cha 9\n\nSkills and Feats: Diplomacy +1, Escape Artist +7, Hide +11, Knowledge (the planes) +6, Listen +7, Search +6, Spot +9, Sense Motive +7, Survival +1 (+3 other planes and following tracks), Swim +10, Use Rope +1 (+3 with bindings); Blind-Fight, Dodge','\n      <div topic=\"Tojanida\" level=\"2\"><p><h2>Tojanida</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Juvenile Tojanida</b><br/></td> \n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Outsider (Extraplanar, Water)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>3d8+6 (19 hp)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>10 ft. (2 squares), swim 90 ft.<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>22 (+1 size, +1 Dex, +10 natural), touch 12, flat-footed 21<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+3/+1<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +6 melee (2d6+2)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +6 melee (2d6+2) and 2 claws +1 melee (1d4+1)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Improved grab, ink cloud<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>All-around vision, darkvision 60 ft., immunity to acid and cold, resistance to<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +5, Ref +4, Will +4<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 14, Dex 13, Con 15, Int 10, Wis 12, Cha 9<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Diplomacy +1, Escape Artist +7, Hide +11, Knowledge (the planes) +6, Listen +7, Search +6, Spot +9, Sense Motive +7, Survival +1 (+3 other planes and following tracks), Swim +10, Use Rope +1 (+3 with bindings)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Blind-Fight, Dodge<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Elemental Plane of Water<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or clutch (2-4)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>3<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>4-6 HD (Small)<br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n</table><p>A tojanida\'s shell is blue-green in color. Inside the shell is a fleshy body from which extend seven stalks. Four of these stalks have paddles for locomotion, two are tipped with claws, and one bears the creature\'s head. Eight vents in the shell, four at each end, allow the tojanida to thrust its stalks out in whatever configuration it finds convenient.</p><p>A juvenile tojanida is up to 25 years old. It has a shell about 3 feet long, and it weighs about 60 pounds. An adult is aged 26 to 80. Its shell is about 6 feet long, and it weighs about 220 pounds. An elder can reach 150 years of age. It has a shell about 9 feet long, and it weighs about 500 pounds.</p><p>Tojanidas speak Aquan and can be loquacious, but usually only on the subject of food.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a tojanida must hit with a bite or claw attack. It can then attempt to start a grapple as a free action without provoking an attack of opportunity. Underwater, a tojanida can tow a grabbed victim of its own size or smaller at its swim speed (but it cannot run). A favorite tactic is to grab a single opponent, then withdraw, hauling the opponent away from its allies.</p>\n</div><div topic=\"Ink Cloud\" level=\"8\"><p><b>Ink Cloud (Ex):</b> A tojanida can emit a spherical cloud of jet-black ink with a radius of 30 feet once per minute as a free action. The effect is otherwise similar to <i>fog cloud</i> cast by an individual of a level equal to the tojanida\'s Hit Dice. Out of water, the ink emerges in a stream up to 30 feet long, which a tojanida can squirt into an opponent\'s eyes. The affected creature must succeed on a Reflex save or be blinded for 1 round. The save DC is 13 against a juvenile, 15 against an adult, and 21 against an elder. The save DCs are Constitution based.</p>\n</div><div topic=\"All-Around Vision\" level=\"8\"><p><b>All-Around Vision (Ex):</b> The multiple apertures in a tojanida\'s shell allow it to look in any direction, bestowing a +4 racial bonus on Spot and Search checks. Opponents gain no flanking bonuses when attacking a tojanida.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A tojanida has a +8 racial bonus on any Swim check to perform some special action or avoid a hazard. It can always choose to take 10 on a Swim check, even if distracted or endangered. It can use the run action while swimming, provided it swims in a straight line.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
